addword('cuisine','fr:cuisine:kitchen','une cuisine','кухня (комната)','юн кюизи́н',ex('Il y a une cuisine.','Есть кухня.','иль я юн кюизи́н'),1,[rev('cuisine-meaning',fr('Une cuisine','юн кюизи́н'),['Спальня','Предмет мебели','Кухня как комната'],2,'Здесь названо помещение кухни.','Нужна кухня как комната; спальня и мебель имеют другой смысл.'),rev('cuisine-use',ru('Нужно сообщить «Есть кухня». Что выбрать?'),[fr('Il y a une cuisine.','иль я юн кюизи́н'),fr('Il y a une chambre.','иль я юн ша́(н)бр'),fr('Il y a un salon.','иль я э(н) сало́(н)')],0,'Выбрана кухня.','Нужна кухня; спальня и гостиная не соответствуют условию.')])
