intro(s,2,'Une pièce — «комната в жилье», une chambre — «спальня», une cuisine — «кухня». Повторяем готовую рамку наличия: Il y a une chambre. — «Есть спальня», Il y a une cuisine. — «Есть кухня». В этих сочетаниях названия показаны с артиклем. Знакомое dans — «внутри; в»: Dans la chambre означает «в спальне».',['piece','chambre','cuisine'],[('Une pièce','юн пьэ́с'),('une chambre','юн ша́(н)бр'),('une cuisine','юн кюизи́н'),('Il y a une chambre.','иль я юн ша́(н)бр'),('Il y a une cuisine.','иль я юн кюизи́н'),('dans','да́(н)'),('Dans la chambre','да(н) ла ша́(н)бр')],('Il y a une chambre. Il y a une cuisine.','иль я юн ша́(н)бр. иль я юн кюизи́н.'))
pairs(s,[U],[('piece','Комната в жилье — общее название'),('chambre','Спальня'),('cuisine','Кухня как комната')],'Вы различили общее название комнаты и два её назначения.','Комната вообще, спальня и кухня — разные по точности названия; сопоставьте каждое с его смыслом.')
listen(s,[U],['chambre','cuisine','table','chaise','dans'],['cuisine','chaise'],'Где по описанию находится стул?','Il y a une chambre. Dans la chambre, il y a une table. Il y a une cuisine. Dans la cuisine, il y a une chaise.','иль я юн ша́(н)бр. да(н) ла ша(н)бр, иль я юн та́бль. иль я юн кюизи́н. да(н) ла кюизин, иль я юн шэ́з.',['В спальне','Место не указано','На кухне'],2,'Стул назван на кухне; в спальне назван стол.','Сопоставьте предмет и комнату в одной фразе: стул относится к кухне, стол — к спальне.')
intro(s,4,'Un salon — «гостиная», un meuble — «предмет мебели». Стол и стул — примеры предметов мебели; спальня и гостиная — комнаты. Образцы: Il y a un salon. — «Есть гостиная», Il y a un meuble. — «Есть предмет мебели». Для перечисления знакомое et означает «и».',['salon','meuble'],[('Un salon','э(н) сало́(н)'),('un meuble','э(н) мё́бль'),('Il y a un salon.','иль я э(н) сало́(н)'),('Il y a un meuble.','иль я э(н) мё́бль'),('et','э')],('Il y a un salon. Il y a un meuble.','иль я э(н) сало́(н). иль я э(н) мё́бль.'))
phrase_pairs(s,[U],[('Dans le salon, il y a une table.','да(н) лё сало(н), иль я юн та́бль.','В гостиной есть стол.',['salon','dans','table'],['salon']),('Un meuble','э(н) мё́бль','Один предмет мебели.',['meuble'],['meuble']),('Une pièce','юн пьэ́с','Комната в жилье.',['piece'],['piece'])],'Вы различили сообщение о гостиной, предмет мебели и комнату.','Предмет мебели не является комнатой; полная фраза уточняет, где находится стол.')
choose(s,'reading',[U],['chambre','cuisine','salon','table','chaise','dans','et'],['salon'],'В какой комнате прямо названы и стол, и стул?',fr('Il y a une chambre, une cuisine et un salon. Dans le salon, il y a une table et une chaise.','иль я юн ша(н)бр, юн кюизин э э(н) сало́(н). да(н) лё сало(н), иль я юн табль э юн шэ́з.'),['В спальне','В гостиной','На кухне'],1,'Оба предмета названы в гостиной.','Перечень комнат не распределяет мебель; расположение двух предметов прямо указано в фразе о гостиной.')
grammar(fill(s,[U],['chambre','un-article','une-article'],[],'Восстановите изученное сочетание в сообщении «Есть спальня».','Il y a ','иль я́',' chambre.','ша́(н)бр',cards(['un-article','une-article']),1,'Il y a une chambre.','иль я юн ша́(н)бр.','Выбран артикль из показанного названия спальни.','Название спальни учится с артиклем женского рода; сохраните это сочетание.'))
order(s,[U],['salon','dans','table','chaise','et'],[],'Соберите «В гостиной есть стол и стул». Начните с комнаты и сохраните названный порядок предметов.',[('Dans le salon,','да(н) лё сало́(н)'),('il y a','иль я́'),('une table','юн та́бль'),('et une chaise.','э юн шэ́з')],'Dans le salon, il y a une table et une chaise.','да(н) лё сало(н), иль я юн табль э юн шэ́з.','Получилось короткое описание комнаты и мебели.','Поставьте комнату первой, затем рамку наличия и два предмета в заданном порядке.')
page(s,[('Комната и мебель',['Названия спальни, кухни и гостиной относятся к комнатам. Стол и стул — предметы мебели; общее название комнаты не заменяет название мебели.'],[ex('Une pièce. Un meuble.','Комната. Предмет мебели.','юн пьэ́с. э(н) мё́бль')]),('Что есть в описании',['Готовая рамка наличия соединяется с показанными названиями и артиклями. Для перечисления используется знакомое и.'],[ex('Il y a une chambre, une cuisine et un salon.','Есть спальня, кухня и гостиная.','иль я юн ша(н)бр, юн кюизин э э(н) сало́(н)')]),('Где находится мебель',['Комната для конкретного предмета берётся из полной фразы. Общий перечень комнат сам по себе не распределяет по ним мебель.'],[W['salon']['example']])])

